import re

def lev(a, b):
    if a == b:
        return 0
    prev = list(range(len(b) + 1))
    for i, ca in enumerate(a, 1):
        cur = [i]
        for j, cb in enumerate(b, 1):
            cur.append(min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (ca != cb)))
        prev = cur
    return prev[-1]

def norm(t):
    return re.sub('\\s+', ' ', t).strip()

def cer(ref, hyp):
    r = norm(ref)
    return round(lev(r, norm(hyp)) / len(r), 4)
(cer('abcd', 'abxd'), cer('a  b\nc', 'a b c'), cer('abcd', ''), cer('abcd', 'abcdefgh'), lev(norm('a  b\nc'), 'a b c'))

